import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { normalizeContext } from "@earendil-works/pi-ai";

export const ccModel = {
	id: "fixture", name: "fixture", api: "anthropic-cc-api", provider: "anthropic-cc", baseUrl: "https://api.anthropic.com", reasoning: false, input: ["text", "image"],
	cost: { input: 1, output: 5, cacheRead: 0.1, cacheWrite: 1.25 }, contextWindow: 100000, maxTokens: 1000,
};
export const rawEvents = [
	{ type: "message_start", message: { id: "fixture", usage: { input_tokens: 1, output_tokens: 0 } } },
	{ type: "content_block_start", index: 0, content_block: { type: "text", text: "" } },
	{ type: "content_block_delta", index: 0, delta: { type: "text_delta", text: "OK" } },
	{ type: "content_block_stop", index: 0 },
	{ type: "message_delta", delta: { stop_reason: "end_turn" }, usage: { output_tokens: 1 } },
	{ type: "message_stop" },
];
export const sse = rawEvents.map(e => `event: ${e.type}\ndata: ${JSON.stringify(e)}\n\n`).join("");

export async function withCcHome<T>(work: () => Promise<T>): Promise<T> {
	const home = mkdtempSync(join(tmpdir(), "pi099-request-"));
	const old = process.env.PI_CODING_AGENT_DIR;
	process.env.PI_CODING_AGENT_DIR = home;
	try { return await work(); }
	finally {
		if (old === undefined) delete process.env.PI_CODING_AGENT_DIR;
		else process.env.PI_CODING_AGENT_DIR = old;
		rmSync(home, { recursive: true, force: true });
	}
}

export async function captureCc(context = normalizeContext({ messages: [{ role: "user", content: "PING", timestamp: 1 }] }), options: any = {}, model: any = ccModel, onNormalized?: (event: any) => void) {
	return withCcHome(async () => {
		const { streamAnthropicCc } = await import("../../src/anthropic-cc/stream");
		const requests: Request[] = [];
		const events: any[] = [];
		const fetch = (async (input: RequestInfo | URL, init?: RequestInit) => {
			const request = new Request(input, init);
			requests.push(request.clone());
			return options.fetch ? options.fetch(input, init) : new Response(sse, { headers: { "content-type": "text/event-stream" } });
		}) as typeof globalThis.fetch;
		const stream = streamAnthropicCc(model, context, { apiKey: "fixture-key", ...options, fetch });
		for await (const event of stream) { onNormalized?.(event); events.push(structuredClone(event)); }
		const message = await stream.result();
		const body = requests[0] ? await requests[0].json() as any : undefined;
		return { requests, body, events, message };
	});
}
